// App.js
import React from 'react';
import ReactDOM from 'react-dom';
// import Carbon CSS
import 'carbon-components/css/carbon-components.min.css';

// Carbon DataTable components
import { DataTable } from 'carbon-components-react';

const {
  TableContainer,
  Table,
  TableHead,
  TableRow,
  TableBody,
  TableCell,
  TableHeader,
} = DataTable;

// sample headers and rows
type Row = { id: string; name: string; description: string; status: string; start: string };

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'description', header: 'Description' },
  { key: 'status', header: 'Status' },
  { key: 'start', header: 'Start Date' },
];

const rows: Row[] = [
  { id: '1', name: 'Program 1', description: 'Description here', status: 'Enrolled', start: '01/01/2017' },
  { id: '2', name: 'Program 2', description: 'Description here', status: 'Complete', start: '01/01/2017' },
  { id: '3', name: 'Program 3', description: 'Description here', status: 'Pending', start: '01/01/2017' },
];

function App() {
  return (
    <div style={{ padding: '2rem' }}>
      <DataTable
        rows={rows}
        headers={headers}
        size="tall"
        isSortable={true}
        render={({ rows, headers, getHeaderProps }) => (
          <TableContainer title="Misaligned Tall Header Demo">
            <Table>
              <TableHead>
                <TableRow>
                  {headers.map((header) => (
                    // only first column is actually sortable in this example
                    <TableHeader
                      key={header.key}
                      {...(header.key === 'name'
                        ? getHeaderProps({ header })
                        : {})}
                    >
                      {header.header}
                    </TableHeader>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {rows.map((row) => (
                  <TableRow key={row.id}>
                    {row.cells.map((cell) => (
                      <TableCell key={cell.id}>{cell.value}</TableCell>
                    ))}
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
